-- Arkentech employee + eSSL mapping import. Private HR data: do not deploy to a web folder.
-- Select u491689847_employeeportal in phpMyAdmin, back up that database, then import this SQL.
-- Adds missing accounts only. Existing profiles, passwords, roles and attendance are preserved.
-- New accounts: firstname.lastname; temporary password User@123; password change required.
-- ID-card Done/Problem values are notes, not employment status.
SET NAMES utf8mb4;
CREATE TEMPORARY TABLE ark_employee_stage_20260924 (
 code VARCHAR(60) PRIMARY KEY, full_name VARCHAR(150), first_name VARCHAR(80), middle_name VARCHAR(100), last_name VARCHAR(80),
 designation VARCHAR(150), username VARCHAR(190) UNIQUE, mobile VARCHAR(40), birth_date DATE NULL, blood_group VARCHAR(10),
 emergency_phone VARCHAR(40), notes VARCHAR(2000), bio VARCHAR(80) UNIQUE, password_hash VARCHAR(255)
) ENGINE=InnoDB;
DROP PROCEDURE IF EXISTS ark_import_employees_20260924;
DELIMITER $$
CREATE PROCEDURE ark_import_employees_20260924()
BEGIN
 DECLARE done INT DEFAULT 0;
 DECLARE actor INT UNSIGNED;
 DECLARE employee_role INT UNSIGNED;
 DECLARE uid INT UNSIGNED;
 DECLARE desig INT UNSIGNED;
 DECLARE maps INT DEFAULT 0;
 DECLARE map_owner INT UNSIGNED;
 DECLARE matched INT DEFAULT 0;
 DECLARE suffix INT DEFAULT 0;
 DECLARE created_count INT DEFAULT 0;
 DECLARE existing_count INT DEFAULT 0;
 DECLARE mapping_count INT DEFAULT 0;
 DECLARE code_v VARCHAR(60);
 DECLARE name_v VARCHAR(150);
 DECLARE first_v VARCHAR(80);
 DECLARE middle_v VARCHAR(100);
 DECLARE last_v VARCHAR(80);
 DECLARE designation_v VARCHAR(150);
 DECLARE base_username VARCHAR(190);
 DECLARE username_v VARCHAR(190);
 DECLARE phone_v VARCHAR(40);
 DECLARE birth_v DATE;
 DECLARE blood_v VARCHAR(10);
 DECLARE emergency_v VARCHAR(40);
 DECLARE notes_v VARCHAR(2000);
 DECLARE bio_v VARCHAR(80);
 DECLARE hash_v VARCHAR(255);
 DECLARE mapping_state VARCHAR(40);
 DECLARE problem VARCHAR(128);
 DECLARE cur CURSOR FOR SELECT * FROM ark_employee_stage_20260924 ORDER BY code;
 DECLARE CONTINUE HANDLER FOR NOT FOUND SET done=1;
 DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
 IF DATABASE() <> 'u491689847_employeeportal' THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Select the Arkentech employeeportal database before importing.';
 END IF;
 IF (SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name IN ('users','employees','roles','user_roles','designations','hr_records','hr_audit') AND engine='InnoDB') <> 7 THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Required transactional HRMS tables are missing. No employee data imported.';
 END IF;
 START TRANSACTION;
 SELECT MIN(id) INTO actor FROM users WHERE role='super_admin' AND active=1;
 IF actor IS NULL THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Active Super Admin not found.'; END IF;
 -- Same configuration lock used by the application and bridge.
 SELECT id INTO actor FROM users WHERE role='super_admin' ORDER BY id LIMIT 1 FOR UPDATE;
 SELECT MIN(id) INTO employee_role FROM roles WHERE slug='employee' AND active=1;
 IF employee_role IS NULL THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Active Employee role not found.'; END IF;
 IF (SELECT COUNT(*) FROM hr_records WHERE module='devices' AND status='Enabled' AND JSON_UNQUOTE(JSON_EXTRACT(data,'$.device_code'))='CQQC231360514') <> 1 THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Exactly one enabled eSSL device CQQC231360514 is required.';
 END IF;
 OPEN cur;
 employee_loop: LOOP
  FETCH cur INTO code_v,name_v,first_v,middle_v,last_v,designation_v,base_username,phone_v,birth_v,blood_v,emergency_v,notes_v,bio_v,hash_v;
  IF done=1 THEN LEAVE employee_loop; END IF;
  SELECT COUNT(*),MIN(user_id) INTO matched,uid FROM employees WHERE employee_code=code_v;
  IF matched>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Duplicate employee code found.'; END IF;
  IF uid IS NOT NULL THEN
   IF NOT EXISTS(SELECT 1 FROM employees e JOIN users u ON u.id=e.user_id WHERE e.user_id=uid AND LOWER(TRIM(e.first_name))=LOWER(first_v) AND LOWER(TRIM(e.last_name))=LOWER(last_v) AND u.role='employee') THEN
    SET problem=CONCAT('Employee identity conflict for ',code_v,'. Import rolled back.');
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT=problem;
   END IF;
   SET existing_count=existing_count+1;
  ELSE
   IF EXISTS(SELECT 1 FROM users WHERE LOWER(TRIM(name))=LOWER(name_v) OR LOWER(username)=LOWER(base_username)) THEN
    SET problem=CONCAT('Existing name or username needs review for ',code_v,'. Import rolled back.');
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT=problem;
   END IF;
   SELECT MIN(id) INTO desig FROM designations WHERE name=designation_v AND department_id IS NULL AND active=1;
   IF desig IS NULL AND designation_v<>'' THEN
    SET desig=LAST_INSERT_ID();
   END IF;
   SET username_v=base_username;
    VALUES(name_v,NULL,username_v,hash_v,'employee',1,1);
   SET uid=LAST_INSERT_ID();
    VALUES(uid,code_v,first_v,middle_v,last_v,desig,phone_v,birth_v,blood_v,emergency_v,notes_v);
   SET created_count=created_count+1;
  END IF;
  SELECT COUNT(*),MIN(employee_id) INTO maps,map_owner FROM hr_records WHERE module='mapping'
   AND JSON_UNQUOTE(JSON_EXTRACT(data,'$.device_code'))='CQQC231360514'
   AND JSON_UNQUOTE(JSON_EXTRACT(data,'$.biometric_id'))=bio_v;
  IF maps>1 OR (maps=1 AND NOT(map_owner <=> uid)) THEN
   SET problem=CONCAT('Conflicting eSSL mapping for ',code_v,'. Import rolled back.');
   SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT=problem;
  END IF;
  IF maps=0 THEN
   SET mapping_state='Inactive';
   IF EXISTS(SELECT 1 FROM users u JOIN employees e ON e.user_id=u.id WHERE u.id=uid AND u.active=1 AND e.deleted_at IS NULL AND e.employment_status IN ('Active','Notice Period')) THEN SET mapping_state='Active'; END IF;
    VALUES('mapping',uid,CONCAT(code_v,' eSSL ',bio_v),mapping_state,JSON_OBJECT('device_code','CQQC231360514','biometric_id',bio_v),actor);
   SET mapping_count=mapping_count+1;
  END IF;
 END LOOP;
 CLOSE cur;
 COMMIT;
 SELECT 'IMPORT COMPLETED' AS result,created_count AS employees_created,existing_count AS existing_employees_preserved,mapping_count AS mappings_created;
END$$
DELIMITER ;
CALL ark_import_employees_20260924();
DROP PROCEDURE ark_import_employees_20260924;
DROP TEMPORARY TABLE ark_employee_stage_20260924;
